for aid in ['a6fd0d22b350ffa51','a72aa6a85c7f90a13']:
    p=f'{base}/agent-{aid}.jsonl'; cmds=[]
    for line in open(p):
        try:o=json.loads(line)
        except:continue
        if o.get('type')!='assistant':continue
        for b in o.get('message',{}).get('content',[]):
            if b.get('type')!='tool_use':continue
            n=b.get('name'); inp=b.get('input',{})
            if n=='Write' and inp.get('file_path'): cmds.append(('write',inp['file_path'],inp.get('content','')))
            elif n=='Edit' and inp.get('file_path'): cmds.append(('edit',inp['file_path'],(inp.get('old_string',''),inp.get('new_string',''),inp.get('replace_all',False))))
            elif n=='Bash':
                c=inp.get('command','')
                if is_mut(c): cmds.append(('bash',c))
    print(aid,len(cmds),flush=True)
    for x in cmds:
        try:
            if x[0]=='write':
                fp,c=x[1],x[2]
                if '/workspace/' in fp: continue
                os.makedirs(os.path.dirname(fp),exist_ok=True); open(fp,'w').write(c)
            elif x[0]=='edit':
                fp,(old,new,ra)=x[1],x[2]
                if '/workspace/' in fp: continue
                try:s=open(fp).read()
                except:continue
                open(fp,'w').write(s.replace(old,new) if ra else s.replace(old,new,1))
            else:
                subprocess.run(['timeout','20','bash','-c',x[1]],cwd='/workspace',stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        except Exception: pass
    print('done',aid,flush=True)
